// Stage only the closed cold-route proposal, with pinned formatting and AST equality.
import fs from'node:fs';import path from'node:path';import assert from'node:assert/strict';import{spawnSync}from'node:child_process';import{createRequire}from'node:module';import{createHash}from'node:crypto';
const p=JSON.parse(fs.readFileSync('../.github/psc1/wire-installed-candidate.json'));assert.equal(p.schema,'psc1-wire-installed-candidate/1');
const sourceCheck=spawnSync('git',['diff','--exit-code',p.baseCommit,'--','packages','host','lakefile.lean','lean-toolchain'],{encoding:'utf8'});assert.equal(sourceCheck.status,0,sourceCheck.stdout+sourceCheck.stderr);
const require=createRequire(path.resolve('host-tools/package.json')),prettier=require('prettier'),{parse}=require('@babel/parser');
const ast=s=>JSON.parse(JSON.stringify(parse(s,{sourceType:'module'}),(k,v)=>['start','end','loc','extra','comments','leadingComments','trailingComments','innerComments'].includes(k)?undefined:v));const pins=[],sources={};
for(const[file,source]of Object.entries(p.files)){assert.equal(file,'psc1/npm-cli/compiler-api.mjs');const formatted=await prettier.format(source,{parser:'babel',singleQuote:true,printWidth:100});assert.deepEqual(ast(formatted),ast(source));fs.writeFileSync(file.slice(5),formatted);pins.push({path:file,bytes:Buffer.byteLength(formatted),sha256:createHash('sha256').update(formatted).digest('hex')});sources[file]=formatted;console.log('PSC1_WIRE_INSTALLED_SOURCE '+JSON.stringify({file,source:formatted}));}
fs.mkdirSync('dist/wire-installed',{recursive:true});fs.writeFileSync('dist/wire-installed/pins.json',JSON.stringify({producerCommit:process.env.GITHUB_SHA,baseCommit:p.baseCommit,pins},null,2)+'\n');fs.writeFileSync('dist/wire-installed/sources.json',JSON.stringify(sources,null,2)+'\n');console.log('PSC1_WIRE_INSTALLED_PINS '+JSON.stringify({producerCommit:process.env.GITHUB_SHA,baseCommit:p.baseCommit,pins}));
